/* ─── bảng màu (đúng token của tap02-full.html) ─── */
const NGA="#C8553D", MY="#2E6F8E", ANH="#7A6A9B", BAC="#F2A33C", VANG="#E8C33C",
      DO="#D4523C", GIAY="#F6F8F5", GIAY2="#ECEFEA", BIENN="#D8ECF7", DATN="#E6E6E6",
      CHUTOI="#1C2A22", NEN="#0A1621", NEN2="#102434", KEE="#1E3A4E", CHU="#EAF2F7",
      CHU2="#8FA8BA", DEN="#0B0B0B", XOVIET="#A8341F", XAM="#9AA7AF";

/* ─── khung ngắm bản đồ (toạ độ bản đồ) ─── */
const V_PANHANDLE = [2238, 1020, 520];
const V_NOME      = [1995,  952, 620];
const V_NOME_SAT  = [1952,  944, 220];   /* cận Nome — cỡ chưa dùng ở đâu khác */
const V_ALASKA    = [2075,  957, 740];
const V_BERING    = [1952,  930, 330];   /* eo Bering: Chukotka đối diện Alaska */
const V_AKCA      = [2235, 1005, 720];
const V_BACMY     = [2400, 1160, 1340];
const V_BACMY_RONG= [2420, 1120, 1560];
const V_THEGIOI   = [1620, 1120, 2860];
const V_BANCAU    = [2210, 1040, 1700];
const V_CUBA      = [2792, 1498, 430];
const V_VINH      = [2660, 1420, 940];
const V_SIBERIA   = [ 980, 1040, 1500];
const V_PRUDHOE   = [2105,  812, 380];

/* ─── tiện ích riêng của khối 3 ─── */
const P = K3M.p;
function bd(root){ const V = root.querySelector("svg.bd"); V.innerHTML = ""; return V; }
function phang(root, ten){ const V = root.querySelector("svg." + ten); V.innerHTML = ""; return V; }
/* nền bản đồ: biển + đất trung tính. toi=true dùng hệ --nen, false dùng hệ --giay */
function nenBD(V, toi){
  el("rect", { x:-9e4, y:-9e4, width:18e4, height:18e4, fill: toi ? "#071420" : BIENN }, V);
  const g = el("g", {}, V);
  K3M.land.forEach(d => el("path", { d: d, fill: toi ? "#14283A" : DATN,
    stroke: toi ? KEE : "#A9BBC7", "stroke-width": .7, "stroke-linejoin": "round",
    "vector-effect": "non-scaling-stroke" }, g));
  return g;
}
/* một vùng chính trị: tô + viền CÙNG MÀU để che đường ghép giữa các dải cắt */
function vung(V, khoa, mau, mo){
  const g = el("g", { opacity: mo === undefined ? 1 : mo }, V);
  K3M["vung_" + khoa].forEach(d => el("path", { d: d, fill: mau, stroke: mau,
    "stroke-width": 1.2, "stroke-linejoin": "round",
    "vector-effect": "non-scaling-stroke" }, g));
  g.__ps = [...g.children];
  return g;
}
const to = (g, mau) => g.__ps.forEach(p => set(p, { fill: mau, stroke: mau }));
/* một tuyến có sẵn trong dữ liệu */
function tuyen(V, khoa, o){
  const g = el("g", {}, V);
  g.__ps = K3M.t[khoa].map(d => el("path", Object.assign({ d: d, fill: "none",
    "stroke-linecap": "round", "stroke-linejoin": "round",
    "vector-effect": "non-scaling-stroke" }, o), g));
  return g;
}
const veDanG = (g, u) => g.__ps.forEach(p => veDan(p, u));
/* máy quay bản đồ: lia + đẩy, LUÔN còn nhịp thở nên không khung nào đứng yên */
function mcam(V, a, b, u, t){
  const e = ezo(cl(u, 0, 1));
  const w = Math.exp(lerp(Math.log(a[2]), Math.log(b[2]), e));
  ngam(V, lerp(a[0], b[0], e) + w * .0045 * Math.sin(t * .23),
          lerp(a[1], b[1], e) + w * .0035 * Math.cos(t * .19), w);
}
/* đứng yên một khung nhưng vẫn đẩy chậm suốt cảnh */
const mgiu = (V, a, u, t, day) => mcam(V, a, [a[0], a[1], a[2] * (day === undefined ? .93 : day)], u, t);
/* nhãn địa danh: hộp trắng chữ đen, tam giác nhọn chỉ xuống (luật F.4) */
function nhanHop(id, ten, l, t){
  return '<div class="tx" id="' + id + '" style="left:' + l + 'px;top:' + t + 'px">' +
    '<div style="background:#FFF;color:#1C2A22;font:700 16px/1 system-ui;letter-spacing:.04em;' +
    'padding:7px 11px;border-radius:3px;white-space:nowrap;box-shadow:0 2px 10px rgba(0,0,0,.45)">' +
    ten + '</div><div style="width:0;height:0;margin:0 auto;border-left:7px solid transparent;' +
    'border-right:7px solid transparent;border-top:9px solid #FFF"></div></div>';
}
/* nhãn pill đỏ cho đường đo (luật F.5) */
function pill(id, ten, l, t){
  return '<div class="tx" id="' + id + '" style="left:' + l + 'px;top:' + t + 'px">' +
    '<div style="background:' + DO + ';color:#FFF;font:700 24px/1 system-ui;padding:9px 16px;' +
    'border-radius:16px;white-space:nowrap">' + ten + '</div></div>';
}
/* năm ở góc trên phải — đồng hồ của video (luật F.6) */
function nam(id, so, toi){
  return '<div class="tx so" id="' + id + '" style="right:48px;top:30px;font:800 46px/1 system-ui;' +
    'letter-spacing:-.03em;color:' + (toi ? BAC : CHUTOI) + ';font-variant-numeric:tabular-nums">' + so + '</div>';
}
/* nhãn vùng lớn: chữ trần giãn, chỉ dùng trong vùng đã tô (luật F.4) */
function nhanVung(id, ten, l, t, mau){
  return '<div class="tx" id="' + id + '" style="left:' + l + 'px;top:' + t + 'px;' +
    'font:700 19px/1 system-ui;letter-spacing:.16em;color:' + (mau || "#FFF") +
    ';text-shadow:0 2px 10px rgba(0,0,0,.85)">' + ten + '</div>';
}
/* Alaska THẬT thu nhỏ, đặt vào bất kỳ chỗ nào của khung 1280x720.
   Dùng <svg> lồng nên viewBox riêng, bộ máy cảnh không đụng tới. */
function miniAK(p, x, y, w, mau, mo){
  const sv = el("svg", { x:x, y:y, width:w, height:(w*386/420).toFixed(1),
    viewBox:"1882 764 420 386", preserveAspectRatio:"xMidYMid meet",
    opacity: mo === undefined ? 1 : mo }, p);
  K3M.vung_alaska.forEach(d => el("path", { d:d, fill:mau, stroke:mau,
    "stroke-width":2.5, "stroke-linejoin":"round" }, sv));
  return sv;
}
/* một người đi bộ — hình khối đặc, đọc ra NGƯỜI chứ không ra chấm */
function nguoiDi(p, mau){
  const g = el("g", {}, p);
  el("circle", { cx:0, cy:-19.5, r:4.2, fill:mau }, g);
  el("path", { d:"M-4.6,-14.2 q4.6,-3.4 9.2,0 l1.5,11.6 l-3.1,.4 l-.9,8.6 l-2.6,0 l-.9,-8.6 l-3.1,-.4 Z",
    fill:mau }, g);
  return g;
}
const nguon = (id, s, l) => '<div class="tx nho" id="' + id + '" style="left:' +
  (l === undefined ? 92 : l) + 'px;top:656px">' + s + '</div>';

