      op(bien, .5*ez((c.t-.1)/.6));
      veDanG(duong, ezo((c.t-.7)/2.2));
      const pt = duong.__ps[0];
      nguoi.forEach((e,i) => {
        const ph = ((c.t*.30) + i/26) % 1;
        const q = diem(pt, ph);
        set(e, { cx:q[0].toFixed(1), cy:q[1].toFixed(1) });
        op(e, (Math.sin(ph*Math.PI) * cl((c.t-.9)/.6,0,1)).toFixed(2));
      });
      ghim("k3c02-nd", V, P.dawson, -56, -56); kh("k3c02-nd", c.t, .4, 3.9);
      ghim("k3c02-ns", V, P.skagway, -84, -56); kh("k3c02-ns", c.t, 1.1, 3.9);
      kh("k3c02-vn", c.t, .2, 3.9); kh("k3c02-vc", c.t, .6, 3.9);
